TEXT ·hasFMA(SB), NOSPLIT, $0-1
	MOVB $0, ret+0(FP)
	MOVL $1, AX
	CPUID
	ANDL $0x18001000, CX // FMA, AVX and OSXSAVE
	CMPL CX, $0x18001000
	JNE hasFMA_unsupported
	XORL CX, CX
	XGETBV
	ANDL $6, AX // XMM and YMM state enabled in XCR0
	CMPL AX, $6
	JNE hasFMA_unsupported
	MOVB $1, ret+0(FP)
hasFMA_unsupported:
	RET

